function parseTask(text) {
  const task = JSON.parse(text);
  return `${task.title} (${task.done ? "done" : "open"})`;
}

const text = JSON.stringify({ id: 1, title: "Buy milk", done: true });
console.log(parseTask(text));
console.log(parseTask('{"id":2,"title":"Call Ada","done":false}'));

