questions.solution:
function countByStatus(tasks) {
  const counts = {};
  for (const task of tasks) {
    counts[task.status] = (counts[task.status] ?? 0) + 1;
  }
  return counts;
}

const tasks = [
  { title: "a", status: "todo" },
  { title: "b", status: "done" },
  { title: "c", status: "todo" },
];
console.log(countByStatus(tasks));

